  1→/* ── SUPER DUPER Design System ──────────────────────────────────────
  2→ *  Brand: #00BB81 (Jade Green)
  3→ *  Surfaces: layered depth, no borders/shadows
  4→ *  Typography: Inter (sans) + JetBrains Mono (mono)
  5→ *  Slot colors: official ComfyUI dark theme
  6→ * ──────────────────────────────────────────────────────────────────── */
  7→
  8→@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap");
  9→
 10→/* ── Design Tokens ──────────────────────────────────────────────── */
 11→
 12→:root {
 13→  /* Brand */
 14→  --sd-brand: #00BB81;
 15→  --sd-brand-dim: #00BB8133;
 16→  --sd-brand-subtle: #00BB8118;
 17→  --sd-dark: #020410;
 18→
 19→  /* Surfaces */
 20→  --sd-canvas: #0d0f14;
 21→  --sd-panel: #141620;
 22→  --sd-card: #1a1d2a;
 23→  --sd-card-hover: #1e2133;
 24→  --sd-elevated: #222538;
 25→  --sd-input: #12141e;
 26→
 27→  /* Text */
 28→  --sd-text-primary: #e8e9ed;
 29→  --sd-text-secondary: #9a9caa;
 30→  --sd-text-muted: #5c5e6e;
 31→  --sd-text-accent: #c0c2ce;
 32→  --sd-text-brand: #00BB81;
 33→
 34→  /* Borders */
 35→  --sd-border: #2a2d3a;
 36→  --sd-border-subtle: #1f2230;
 37→
 38→  /* Slot Colors (ComfyUI dark theme) */
 39→  --sd-slot-clip: #FFD500;
 40→  --sd-slot-clip-vision: #A8DADC;
 41→  --sd-slot-conditioning: #FFA931;
 42→  --sd-slot-controlnet: #6EE7B7;
 43→  --sd-slot-image: #64B5F6;
 44→  --sd-slot-latent: #FF9CF9;
 45→  --sd-slot-mask: #81C784;
 46→  --sd-slot-model: #B39DDB;
 47→  --sd-slot-style-model: #C2FFAE;
 48→  --sd-slot-vae: #FF6E6E;
 49→  --sd-slot-noise: #B0B0B0;
 50→  --sd-slot-guider: #66FFFF;
 51→  --sd-slot-sampler: #ECB4B4;
 52→  --sd-slot-sigmas: #CDFFCD;
 53→
 54→  /* Typography */
 55→  --sd-font-sans: "Inter", "SF Pro Display", system-ui, -apple-system, sans-serif;
 56→  --sd-font-mono: "JetBrains Mono", "Fira Code", "SF Mono", "Cascadia Code", monospace;
 57→
 58→  /* Spacing */
 59→  --sd-space-xs: 4px;
 60→  --sd-space-sm: 6px;
 61→  --sd-space-md: 8px;
 62→  --sd-space-lg: 12px;
 63→  --sd-space-xl: 16px;
 64→
 65→  /* Transitions */
 66→  --sd-transition: 150ms ease;
 67→}
 68→
 69→/* ── Layout Shell ───────────────────────────────────────────────── */
 70→
 71→.sd-header {
 72→  display: flex;
 73→  align-items: center;
 74→  justify-content: space-between;
 75→  padding: var(--sd-space-lg) var(--sd-space-xl);
 76→  font-family: var(--sd-font-sans);
 77→  font-size: 14px;
 78→  font-weight: 700;
 79→  letter-spacing: 0.5px;
 80→  color: var(--sd-text-brand);
 81→  border-bottom: 1px solid var(--sd-border);
 82→  background: var(--sd-panel);
 83→  flex-shrink: 0;
 84→}
 85→
 86→.sd-header__title {
 87→  flex: 1;
 88→}
 89→
 90→.sd-header__status {
 91→  font-family: var(--sd-font-mono);
 92→  font-size: 10px;
 93→  font-weight: 400;
 94→  color: var(--sd-text-muted);
 95→  text-transform: uppercase;
 96→  letter-spacing: 0.06em;
 97→}
 98→
 99→.sd-header__status--connecting {
100→  color: var(--sd-slot-conditioning);
101→}
102→
103→.sd-header__status--disconnected {
104→  color: var(--sd-slot-vae);
105→}
106→
107→/* ── Stage Indicator ────────────────────────────────────────────── */
108→
109→.sd-stage-bar {
110→  display: flex;
111→  align-items: center;
112→  gap: var(--sd-space-md);
113→  padding: var(--sd-space-sm) var(--sd-space-xl);
114→  background: var(--sd-brand-subtle);
115→  border-bottom: 1px solid var(--sd-border);
116→  flex-shrink: 0;
117→  font-size: 12px;
118→  animation: sd-pulse 1.5s ease-in-out infinite;
119→}
120→
121→.sd-stage__label {
122→  font-family: var(--sd-font-mono);
123→  color: var(--sd-text-brand);
124→  font-weight: 600;
125→  font-size: 10px;
126→  letter-spacing: 0.06em;
127→  text-transform: uppercase;
128→}
129→
130→.sd-stage__detail {
131→  font-family: var(--sd-font-sans);
132→  color: var(--sd-text-muted);
133→  font-size: 11px;
134→}
135→
136→@keyframes sd-pulse {
137→  0%, 100% { opacity: 1; }
138→  50% { opacity: 0.6; }
139→}
140→
141→/* ── Messages Area ──────────────────────────────────────────────── */
142→
143→.sd-messages {
144→  flex: 1;
145→  overflow-y: auto;
146→  padding: var(--sd-space-lg);
147→  display: flex;
148→  flex-direction: column;
149→  gap: var(--sd-space-md);
150→  background: var(--sd-canvas);
151→}
152→
153→/* ── Message Bubbles ────────────────────────────────────────────── */
154→
155→.sd-message {
156→  display: flex;
157→  flex-direction: column;
158→  gap: 2px;
159→  padding: var(--sd-space-md) 10px;
160→  border-radius: 6px;
161→  font-family: var(--sd-font-sans);
162→  font-size: 12px;
163→  line-height: 1.5;
164→  word-wrap: break-word;
165→}
166→
167→.sd-message--user {
168→  background: var(--sd-card);
169→  align-self: flex-end;
170→  max-width: 90%;
171→}
172→
173→.sd-message--agent {
174→  background: var(--sd-panel);
175→  align-self: flex-start;
176→  max-width: 95%;
177→}
178→
179→.sd-message--system {
180→  background: transparent;
181→  color: var(--sd-text-muted);
182→  font-style: italic;
183→  font-size: 11px;
184→  align-self: center;
185→}
186→
187→.sd-message__label {
188→  font-family: var(--sd-font-mono);
189→  font-size: 10px;
190→  font-weight: 400;
191→  color: var(--sd-text-muted);
192→  text-transform: uppercase;
193→  letter-spacing: 0.06em;
194→}
195→
196→.sd-message--user .sd-message__label {
197→  color: var(--sd-text-accent);
198→}
199→
200→.sd-message--agent .sd-message__label {
201→  color: var(--sd-text-brand);
202→}
203→
204→.sd-message__body {
205→  color: var(--sd-text-secondary);
206→}
207→
208→.sd-message--user .sd-message__body {
209→  color: var(--sd-text-primary);
210→}
211→
212→.sd-message--system .sd-message__body {
213→  color: var(--sd-text-muted);
214→}
215→
216→/* ── Text Rendering Classes ─────────────────────────────────────── */
217→
218→.sd-text-body {
219→  font-family: var(--sd-font-sans);
220→  font-size: 12px;
221→  color: var(--sd-text-secondary);
222→  line-height: 1.5;
223→}
224→
225→.sd-text-body p {
226→  margin: 0 0 var(--sd-space-md) 0;
227→}
228→
229→.sd-text-body p:last-child {
230→  margin-bottom: 0;
231→}
232→
233→.sd-code-inline {
234→  font-family: var(--sd-font-mono);
235→  font-size: 11px;
236→  background: var(--sd-elevated);
237→  color: var(--sd-text-accent);
238→  padding: 1px 5px;
239→  border-radius: 3px;
240→  letter-spacing: 0.01em;
241→}
242→
243→.sd-code-block {
244→  font-family: var(--sd-font-mono);
245→  font-size: 11px;
246→  line-height: 1.5;
247→  background: var(--sd-input);
248→  color: var(--sd-text-primary);
249→  padding: var(--sd-space-md) var(--sd-space-lg);
250→  border-radius: 4px;
251→  border: 1px solid var(--sd-border-subtle);
252→  margin: var(--sd-space-md) 0;
253→  overflow-x: auto;
254→  white-space: pre;
255→}
256→
257→.sd-text-bold {
258→  font-weight: 600;
259→  color: var(--sd-text-primary);
260→}
261→
262→/* ── Typing Indicator ───────────────────────────────────────────── */
263→
264→.sd-typing {
265→  display: inline-flex;
266→  align-items: center;
267→  gap: 4px;
268→  padding: 4px 0;
269→}
270→
271→.sd-typing__dot {
272→  width: 5px;
273→  height: 5px;
274→  border-radius: 50%;
275→  background: var(--sd-brand);
276→  animation: sd-typing-pulse 1.2s ease-in-out infinite;
277→}
278→
279→.sd-typing__dot:nth-child(2) {
280→  animation-delay: 0.15s;
281→}
282→
283→.sd-typing__dot:nth-child(3) {
284→  animation-delay: 0.3s;
285→}
286→
287→@keyframes sd-typing-pulse {
288→  0%, 60%, 100% { opacity: 0.3; transform: scale(0.8); }
289→  30% { opacity: 1; transform: scale(1); }
290→}
291→
292→/* ── Input Bar ──────────────────────────────────────────────────── */
293→
294→.sd-input-bar {
295→  display: flex;
296→  gap: var(--sd-space-sm);
297→  padding: 10px var(--sd-space-lg);
298→  border-top: 1px solid var(--sd-border);
299→  background: var(--sd-panel);
300→  flex-shrink: 0;
301→}
302→
303→.sd-input {
304→  flex: 1;
305→  background: var(--sd-input);
306→  border: 1px solid var(--sd-border);
307→  border-radius: 6px;
308→  padding: var(--sd-space-md) 10px;
309→  color: var(--sd-text-primary);
310→  font-family: var(--sd-font-sans);
311→  font-size: 12px;
312→  outline: none;
313→  transition: border-color var(--sd-transition);
314→}
315→
316→.sd-input:focus {
317→  border-color: var(--sd-brand);
318→}
319→
320→.sd-input::placeholder {
321→  color: var(--sd-text-muted);
322→}
323→
324→.sd-send-btn {
325→  background: var(--sd-brand);
326→  color: var(--sd-dark);
327→  border: none;
328→  border-radius: 6px;
329→  padding: var(--sd-space-md) 14px;
330→  font-family: var(--sd-font-sans);
331→  font-size: 12px;
332→  font-weight: 600;
333→  cursor: pointer;
334→  transition: background var(--sd-transition), opacity var(--sd-transition);
335→  flex-shrink: 0;
336→}
337→
338→.sd-send-btn:hover {
339→  opacity: 0.9;
340→}
341→
342→.sd-send-btn:active {
343→  opacity: 0.8;
344→}
345→
346→.sd-send-btn:disabled {
347→  background: var(--sd-elevated);
348→  color: var(--sd-text-muted);
349→  cursor: not-allowed;
350→  opacity: 1;
351→}
352→
353→/* ── Scrollbar ──────────────────────────────────────────────────── */
354→
355→.sd-messages::-webkit-scrollbar {
356→  width: 3px;
357→}
358→
359→.sd-messages::-webkit-scrollbar-track {
360→  background: transparent;
361→}
362→
363→.sd-messages::-webkit-scrollbar-thumb {
364→  background: var(--sd-border);
365→  border-radius: 2px;
366→}
367→
368→.sd-messages::-webkit-scrollbar-thumb:hover {
369→  background: var(--sd-text-muted);
370→}
371→
372→/* ── Panel Components ───────────────────────────────────────────── */
373→
374→/* Panel container */
375→.sd-panel {
376→  background: var(--sd-panel);
377→  border-radius: 6px;
378→  border: 1px solid var(--sd-border-subtle);
379→  overflow: hidden;
380→  margin: var(--sd-space-xs) 0;
381→  max-width: 100%;
382→}
383→
384→/* Panel header */
385→.sd-panel__header {
386→  padding: var(--sd-space-xl) 14px 14px;
387→}
388→
389→.sd-panel__label-row {
390→  display: flex;
391→  align-items: center;
392→  justify-content: space-between;
393→  margin-bottom: var(--sd-space-md);
394→}
395→
396→.sd-panel__label {
397→  font-family: var(--sd-font-mono);
398→  font-size: 10px;
399→  font-weight: 400;
400→  color: var(--sd-text-muted);
401→  text-transform: uppercase;
402→  letter-spacing: 0.06em;
403→}
404→
405→.sd-panel__badge {
406→  font-family: var(--sd-font-mono);
407→  font-size: 10px;
408→  font-weight: 400;
409→  color: var(--sd-text-brand);
410→  background: var(--sd-brand-subtle);
411→  padding: 2px 8px;
412→  border-radius: 3px;
413→  letter-spacing: 0.01em;
414→}
415→
416→.sd-panel__title {
417→  font-family: var(--sd-font-sans);
418→  font-size: 16px;
419→  font-weight: 600;
420→  color: var(--sd-text-primary);
421→  letter-spacing: -0.02em;
422→  margin-bottom: var(--sd-space-sm);
423→  line-height: 1.3;
424→}
425→
426→.sd-panel__summary {
427→  font-family: var(--sd-font-sans);
428→  font-size: 12px;
429→  color: var(--sd-text-secondary);
430→  line-height: 1.5;
431→  margin-bottom: var(--sd-space-lg);
432→}
433→
434→.sd-panel__stats {
435→  display: flex;
436→  gap: var(--sd-space-xl);
437→}
438→
439→.sd-panel__stat {
440→  display: flex;
441→  flex-direction: column;
442→  gap: 1px;
443→}
444→
445→.sd-panel__stat-value {
446→  font-family: var(--sd-font-mono);
447→  font-size: 14px;
448→  font-weight: 600;
449→  color: var(--sd-text-primary);
450→}
451→
452→.sd-panel__stat-label {
453→  font-family: var(--sd-font-sans);
454→  font-size: 10px;
455→  color: var(--sd-text-muted);
456→}
457→
458→/* Collapsible section */
459→.sd-section {
460→  border-top: 1px solid var(--sd-border-subtle);
461→}
462→
463→.sd-section__trigger {
464→  display: flex;
465→  align-items: center;
466→  width: 100%;
467→  padding: 10px 14px;
468→  background: none;
469→  border: none;
470→  cursor: pointer;
471→  color: var(--sd-text-primary);
472→  font-family: var(--sd-font-sans);
473→  font-size: 12px;
474→  font-weight: 500;
475→  letter-spacing: 0.01em;
476→  text-align: left;
477→  gap: var(--sd-space-md);
478→  transition: background var(--sd-transition);
479→}
480→
481→.sd-section__trigger:hover {
482→  background: var(--sd-card);
483→}
484→
485→.sd-section__dot {
486→  width: 5px;
487→  height: 5px;
488→  border-radius: 50%;
489→  flex-shrink: 0;
490→}
491→
492→.sd-section__title {
493→  flex: 1;
494→}
495→
496→.sd-section__count {
497→  font-family: var(--sd-font-mono);
498→  font-size: 10px;
499→  color: var(--sd-text-muted);
500→  letter-spacing: 0.01em;
501→}
502→
503→.sd-section__chevron {
504→  font-size: 10px;
505→  color: var(--sd-text-muted);
