521→}
522→
523→/* Slot tag */
524→.sd-slot-tag {
525→  display: inline-flex;
526→  align-items: center;
527→  gap: var(--sd-space-xs);
528→  padding: 2px 8px 2px 6px;
529→  border-radius: 3px;
530→  font-family: var(--sd-font-mono);
531→  font-size: 11px;
532→  letter-spacing: 0.01em;
533→  margin: 0 var(--sd-space-xs) var(--sd-space-xs) 0;
534→}
535→
536→.sd-slot-tag__dot {
537→  width: 5px;
538→  height: 5px;
539→  border-radius: 50%;
540→  flex-shrink: 0;
541→}
542→
543→/* Flow chain */
544→.sd-flow-chain {
545→  display: flex;
546→  flex-wrap: wrap;
547→  align-items: center;
548→  gap: 2px;
549→  padding: var(--sd-space-xs) 0;
550→}
551→
552→.sd-flow-chain__label {
553→  font-family: var(--sd-font-mono);
554→  font-size: 10px;
555→  color: var(--sd-text-muted);
556→  text-transform: uppercase;
557→  letter-spacing: 0.06em;
558→  margin-right: var(--sd-space-md);
