290→}
291→
292→/* ── Input Bar ──────────────────────────────────────────────────── */
293→
294→.sd-input-bar {
295→  display: flex;
296→  gap: var(--sd-space-sm);
297→  padding: 10px var(--sd-space-lg);
298→  border-top: 1px solid var(--sd-border);
299→  background: var(--sd-panel);
300→  flex-shrink: 0;
301→}
302→
303→.sd-input {
304→  flex: 1;
305→  background: var(--sd-input);
306→  border: 1px solid var(--sd-border);
307→  border-radius: 6px;
308→  padding: var(--sd-space-md) 10px;
