/* ── SUPER DUPER Design System ──────────────────────────────────────
 *  Brand: #00BB81 (Jade Green)
 *  Surfaces: layered depth, no borders/shadows
 *  Typography: Inter (sans) + JetBrains Mono (mono)
 *  Slot colors: official ComfyUI dark theme
 * ──────────────────────────────────────────────────────────────────── */

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap");

/* ── Design Tokens ──────────────────────────────────────────────── */

:root {
  /* Brand */
  --sd-brand: #00BB81;
  --sd-brand-dim: #00BB8133;
  --sd-brand-subtle: #00BB8118;
  --sd-dark: #020410;

  /* Surfaces */
  --sd-canvas: #0d0f14;
  --sd-panel: #141620;
  --sd-card: #1a1d2a;
  --sd-card-hover: #1e2133;
  --sd-elevated: #222538;
  --sd-input: #12141e;

  /* Text */
  --sd-text-primary: #e8e9ed;
  --sd-text-secondary: #9a9caa;
  --sd-text-muted: #5c5e6e;
  --sd-text-accent: #c0c2ce;
  --sd-text-brand: #00BB81;

  /* Borders */
  --sd-border: #2a2d3a;
  --sd-border-subtle: #1f2230;

  /* Slot Colors (ComfyUI dark theme) */
  --sd-slot-clip: #FFD500;
  --sd-slot-clip-vision: #A8DADC;
  --sd-slot-conditioning: #FFA931;
  --sd-slot-controlnet: #6EE7B7;
  --sd-slot-image: #64B5F6;
  --sd-slot-latent: #FF9CF9;
  --sd-slot-mask: #81C784;
  --sd-slot-model: #B39DDB;
  --sd-slot-style-model: #C2FFAE;
  --sd-slot-vae: #FF6E6E;
  --sd-slot-noise: #B0B0B0;
  --sd-slot-guider: #66FFFF;
  --sd-slot-sampler: #ECB4B4;
  --sd-slot-sigmas: #CDFFCD;

  /* Typography */
  --sd-font-sans: "Inter", "SF Pro Display", system-ui, -apple-system, sans-serif;
  --sd-font-mono: "JetBrains Mono", "Fira Code", "SF Mono", "Cascadia Code", monospace;

  /* Spacing */
  --sd-space-xs: 4px;
  --sd-space-sm: 6px;
  --sd-space-md: 8px;
  --sd-space-lg: 12px;
  --sd-space-xl: 16px;

  /* Transitions */
  --sd-transition: 150ms ease;
}

/* ── Layout Shell ───────────────────────────────────────────────── */

.sd-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--sd-space-lg) var(--sd-space-xl);
  font-family: var(--sd-font-sans);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--sd-text-brand);
  border-bottom: 1px solid var(--sd-border);
  background: var(--sd-panel);
  flex-shrink: 0;
}

.sd-header__title {
  flex: 1;
}

.sd-header__status {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sd-header__status--connecting {
  color: var(--sd-slot-conditioning);
}

.sd-header__status--disconnected {
  color: var(--sd-slot-vae);
}

/* ── Stage Indicator ────────────────────────────────────────────── */

.sd-stage-bar {
  display: flex;
  align-items: center;
  gap: var(--sd-space-md);
  padding: var(--sd-space-sm) var(--sd-space-xl);
  background: var(--sd-brand-subtle);
  border-bottom: 1px solid var(--sd-border);
  flex-shrink: 0;
  font-size: 12px;
  animation: sd-pulse 1.5s ease-in-out infinite;
}

.sd-stage__label {
  font-family: var(--sd-font-mono);
  color: var(--sd-text-brand);
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.sd-stage__detail {
  font-family: var(--sd-font-sans);
  color: var(--sd-text-muted);
  font-size: 11px;
}

@keyframes sd-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* ── Messages Area ──────────────────────────────────────────────── */

.sd-messages {
  flex: 1;
  overflow-y: auto;
  padding: var(--sd-space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--sd-space-md);
  background: var(--sd-canvas);
}

/* ── Message Bubbles ────────────────────────────────────────────── */

.sd-message {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: var(--sd-space-md) 10px;
  border-radius: 6px;
  font-family: var(--sd-font-sans);
  font-size: 12px;
  line-height: 1.5;
  word-wrap: break-word;
}

.sd-message--user {
  background: var(--sd-card);
  align-self: flex-end;
  max-width: 90%;
}

.sd-message--agent {
  background: var(--sd-panel);
  align-self: flex-start;
  max-width: 95%;
}

.sd-message--system {
  background: transparent;
  color: var(--sd-text-muted);
  font-style: italic;
  font-size: 11px;
  align-self: center;
}

.sd-message__label {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sd-message--user .sd-message__label {
  color: var(--sd-text-accent);
}

.sd-message--agent .sd-message__label {
  color: var(--sd-text-brand);
}

.sd-message__body {
  color: var(--sd-text-secondary);
}

.sd-message--user .sd-message__body {
  color: var(--sd-text-primary);
}

.sd-message--system .sd-message__body {
  color: var(--sd-text-muted);
}

/* ── Text Rendering Classes ─────────────────────────────────────── */

.sd-text-body {
  font-family: var(--sd-font-sans);
  font-size: 12px;
  color: var(--sd-text-secondary);
  line-height: 1.5;
}

.sd-text-body p {
  margin: 0 0 var(--sd-space-md) 0;
}

.sd-text-body p:last-child {
  margin-bottom: 0;
}

.sd-code-inline {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  background: var(--sd-elevated);
  color: var(--sd-text-accent);
  padding: 1px 5px;
  border-radius: 3px;
  letter-spacing: 0.01em;
}

.sd-code-block {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  line-height: 1.5;
  background: var(--sd-input);
  color: var(--sd-text-primary);
  padding: var(--sd-space-md) var(--sd-space-lg);
  border-radius: 4px;
  border: 1px solid var(--sd-border-subtle);
  margin: var(--sd-space-md) 0;
  overflow-x: auto;
  white-space: pre;
}

.sd-text-bold {
  font-weight: 600;
  color: var(--sd-text-primary);
}

/* ── Typing Indicator ───────────────────────────────────────────── */

.sd-typing {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 0;
}

.sd-typing__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--sd-brand);
  animation: sd-typing-pulse 1.2s ease-in-out infinite;
}

.sd-typing__dot:nth-child(2) {
  animation-delay: 0.15s;
}

.sd-typing__dot:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes sd-typing-pulse {
  0%, 60%, 100% { opacity: 0.3; transform: scale(0.8); }
  30% { opacity: 1; transform: scale(1); }
}

/* ── Input Bar ──────────────────────────────────────────────────── */

.sd-input-bar {
  display: flex;
  gap: var(--sd-space-sm);
  padding: 10px var(--sd-space-lg);
  border-top: 1px solid var(--sd-border);
  background: var(--sd-panel);
  flex-shrink: 0;
}

.sd-input {
  flex: 1;
  background: var(--sd-input);
  border: 1px solid var(--sd-border);
  border-radius: 6px;
  padding: var(--sd-space-md) 10px;
  color: var(--sd-text-primary);
  font-family: var(--sd-font-sans);
  font-size: 12px;
  outline: none;
  transition: border-color var(--sd-transition);
}

.sd-input:focus {
  border-color: var(--sd-brand);
}

.sd-input::placeholder {
  color: var(--sd-text-muted);
}

.sd-send-btn {
  background: var(--sd-brand);
  color: var(--sd-dark);
  border: none;
  border-radius: 6px;
  padding: var(--sd-space-md) 14px;
  font-family: var(--sd-font-sans);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--sd-transition), opacity var(--sd-transition);
  flex-shrink: 0;
}

.sd-send-btn:hover {
  opacity: 0.9;
}

.sd-send-btn:active {
  opacity: 0.8;
}

.sd-send-btn:disabled {
  background: var(--sd-elevated);
  color: var(--sd-text-muted);
  cursor: not-allowed;
  opacity: 1;
}

/* ── Scrollbar ──────────────────────────────────────────────────── */

.sd-messages::-webkit-scrollbar {
  width: 3px;
}

.sd-messages::-webkit-scrollbar-track {
  background: transparent;
}

.sd-messages::-webkit-scrollbar-thumb {
  background: var(--sd-border);
  border-radius: 2px;
}

.sd-messages::-webkit-scrollbar-thumb:hover {
  background: var(--sd-text-muted);
}

/* ── Panel Components ───────────────────────────────────────────── */

/* Panel container */
.sd-panel {
  background: var(--sd-panel);
  border-radius: 6px;
  border: 1px solid var(--sd-border-subtle);
  overflow: hidden;
  margin: var(--sd-space-xs) 0;
  max-width: 100%;
}

/* Panel header */
.sd-panel__header {
  padding: var(--sd-space-xl) 14px 14px;
}

.sd-panel__label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--sd-space-md);
}

.sd-panel__label {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sd-panel__badge {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-text-brand);
  background: var(--sd-brand-subtle);
  padding: 2px 8px;
  border-radius: 3px;
  letter-spacing: 0.01em;
}

.sd-panel__title {
  font-family: var(--sd-font-sans);
  font-size: 16px;
  font-weight: 600;
  color: var(--sd-text-primary);
  letter-spacing: -0.02em;
  margin-bottom: var(--sd-space-sm);
  line-height: 1.3;
}

.sd-panel__summary {
  font-family: var(--sd-font-sans);
  font-size: 12px;
  color: var(--sd-text-secondary);
  line-height: 1.5;
  margin-bottom: var(--sd-space-lg);
}

.sd-panel__stats {
  display: flex;
  gap: var(--sd-space-xl);
}

.sd-panel__stat {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.sd-panel__stat-value {
  font-family: var(--sd-font-mono);
  font-size: 14px;
  font-weight: 600;
  color: var(--sd-text-primary);
}

.sd-panel__stat-label {
  font-family: var(--sd-font-sans);
  font-size: 10px;
  color: var(--sd-text-muted);
}

/* Collapsible section */
.sd-section {
  border-top: 1px solid var(--sd-border-subtle);
}

.sd-section__trigger {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 10px 14px;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--sd-text-primary);
  font-family: var(--sd-font-sans);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.01em;
  text-align: left;
  gap: var(--sd-space-md);
  transition: background var(--sd-transition);
}

.sd-section__trigger:hover {
  background: var(--sd-card);
}

.sd-section__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  flex-shrink: 0;
}

.sd-section__title {
  flex: 1;
}

.sd-section__count {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: var(--sd-text-muted);
  letter-spacing: 0.01em;
}

.sd-section__chevron {
  font-size: 10px;
  color: var(--sd-text-muted);
  transition: transform var(--sd-transition);
  flex-shrink: 0;
}

.sd-section--open > .sd-section__trigger .sd-section__chevron {
  transform: rotate(90deg);
}

.sd-section__body {
  padding: 0 14px 12px;
  display: none;
}

.sd-section--open > .sd-section__body {
  display: block;
}

/* Slot tag */
.sd-slot-tag {
  display: inline-flex;
  align-items: center;
  gap: var(--sd-space-xs);
  padding: 2px 8px 2px 6px;
  border-radius: 3px;
  font-family: var(--sd-font-mono);
  font-size: 11px;
  letter-spacing: 0.01em;
  margin: 0 var(--sd-space-xs) var(--sd-space-xs) 0;
}

.sd-slot-tag__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* Flow chain */
.sd-flow-chain {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;
  padding: var(--sd-space-xs) 0;
}

.sd-flow-chain__label {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-right: var(--sd-space-md);
  width: 100%;
  margin-bottom: var(--sd-space-xs);
}

.sd-flow-chain__node {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 3px;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.sd-flow-chain__arrow {
  color: var(--sd-text-muted);
  font-size: 10px;
  padding: 0 2px;
  user-select: none;
}

/* Detail row */
.sd-detail-row {
  display: flex;
  align-items: baseline;
  gap: var(--sd-space-md);
  padding: var(--sd-space-xs) 0;
}

.sd-detail-row__label {
  font-family: var(--sd-font-sans);
  font-size: 11px;
  color: var(--sd-text-muted);
  white-space: nowrap;
}

.sd-detail-row__leader {
  flex: 1;
  border-bottom: 1px dotted var(--sd-border);
  min-width: 16px;
  margin-bottom: 3px;
}

.sd-detail-row__value {
  font-family: var(--sd-font-mono);
  font-size: 10.5px;
  color: var(--sd-text-secondary);
  letter-spacing: 0.01em;
  white-space: nowrap;
  text-align: right;
}

/* Capability row */
.sd-capability-row {
  display: flex;
  align-items: baseline;
  gap: var(--sd-space-md);
  padding: var(--sd-space-xs) 0;
}

.sd-capability-row__dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 5px;
}

.sd-capability-row__label {
  font-family: var(--sd-font-sans);
  font-size: 11px;
  font-weight: 500;
  color: var(--sd-text-accent);
  white-space: nowrap;
}

.sd-capability-row__sep {
  flex: 1;
  border-bottom: 1px solid var(--sd-border-subtle);
  min-width: 12px;
  margin-bottom: 3px;
}

.sd-capability-row__desc {
  font-family: var(--sd-font-sans);
  font-size: 10.5px;
  color: var(--sd-text-muted);
  text-align: right;
}

/* Action footer */
.sd-panel__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-top: 1px solid var(--sd-border-subtle);
}

.sd-panel__footer-status {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: var(--sd-text-muted);
  letter-spacing: 0.01em;
}

.sd-panel__footer-actions {
  display: flex;
  gap: var(--sd-space-sm);
}

.sd-btn {
  font-family: var(--sd-font-sans);
  font-size: 11px;
  font-weight: 500;
  padding: 5px 14px;
  border-radius: 4px;
  cursor: pointer;
  transition: opacity var(--sd-transition), background var(--sd-transition);
}

.sd-btn--secondary {
  background: transparent;
  border: 1px solid var(--sd-border);
  color: var(--sd-text-secondary);
}

.sd-btn--secondary:hover {
  background: var(--sd-card);
}

.sd-btn--primary {
  background: var(--sd-brand);
  border: none;
  color: var(--sd-dark);
  font-weight: 600;
}

.sd-btn--primary:hover {
  opacity: 0.9;
}

/* Slot tags container */
.sd-slot-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sd-space-xs);
  padding: var(--sd-space-xs) 0;
}

content.content:
  1→/* ── SUPER DUPER Chat Renderer ──────────────────────────────────────
  2→ *  Text rendering (Phase 1) + Panel component factories (Phase 2).
  3→ *  No innerHTML anywhere — all DOM built via createElement + textContent.
  4→ * ──────────────────────────────────────────────────────────────────── */
  5→
  6→// ── Slot Colors ────────────────────────────────────────────────────
  7→
  8→export const SLOT_COLORS = {
  9→  clip:         { color: "#FFD500", varName: "--sd-slot-clip" },
 10→  clip_vision:  { color: "#A8DADC", varName: "--sd-slot-clip-vision" },
 11→  conditioning: { color: "#FFA931", varName: "--sd-slot-conditioning" },
 12→  controlnet:   { color: "#6EE7B7", varName: "--sd-slot-controlnet" },
 13→  image:        { color: "#64B5F6", varName: "--sd-slot-image" },
 14→  latent:       { color: "#FF9CF9", varName: "--sd-slot-latent" },
 15→  mask:         { color: "#81C784", varName: "--sd-slot-mask" },
 16→  model:        { color: "#B39DDB", varName: "--sd-slot-model" },
 17→  style_model:  { color: "#C2FFAE", varName: "--sd-slot-style-model" },
 18→  vae:          { color: "#FF6E6E", varName: "--sd-slot-vae" },
 19→  noise:        { color: "#B0B0B0", varName: "--sd-slot-noise" },
 20→  guider:       { color: "#66FFFF", varName: "--sd-slot-guider" },
 21→  sampler:      { color: "#ECB4B4", varName: "--sd-slot-sampler" },
 22→  sigmas:       { color: "#CDFFCD", varName: "--sd-slot-sigmas" },
 23→};
 24→
 25→function _slotColor(slotType) {
 26→  const s = SLOT_COLORS[slotType];
 27→  return s ? s.color : "#9a9caa";
 28→}
 29→
 30→// ── Text Rendering ─────────────────────────────────────────────────
 31→
 32→/**
 33→ * Parse raw text into a DocumentFragment with styled elements.
 34→ * Handles: ```code blocks```, `inline code`, **bold**, paragraph breaks.
 35→ * NO innerHTML — all content via textContent.
 36→ */
 37→export function renderText(rawText) {
 38→  const frag = document.createDocumentFragment();
 39→  if (!rawText) return frag;
 40→
 41→  // Split on triple-backtick code blocks
 42→  const parts = rawText.split(/(```[\s\S]*?```)/);
 43→
 44→  for (const part of parts) {
 45→    if (part.startsWith("```") && part.endsWith("```")) {
 46→      // Code block — strip fences and optional language tag
 47→      let code = part.slice(3, -3);
 48→      // Remove optional language identifier on first line
 49→      const nlIdx = code.indexOf("\n");
 50→      if (nlIdx !== -1 && nlIdx < 20 && /^[a-zA-Z]*$/.test(code.slice(0, nlIdx).trim())) {
 51→        code = code.slice(nlIdx + 1);
 52→      }
 53→      // Trim leading/trailing newline
 54→      if (code.startsWith("\n")) code = code.slice(1);
 55→      if (code.endsWith("\n")) code = code.slice(0, -1);
 56→
 57→      const pre = document.createElement("pre");
 58→      pre.className = "sd-code-block";
 59→      pre.textContent = code;
 60→      frag.appendChild(pre);
 61→    } else {
 62→      // Text content — split into paragraphs on double newlines
 63→      const paragraphs = part.split(/\n{2,}/);
 64→      for (const para of paragraphs) {
 65→        const trimmed = para.trim();
 66→        if (!trimmed) continue;
 67→
 68→        const p = document.createElement("p");
 69→        _appendInlineMarkup(p, trimmed);
 70→        frag.appendChild(p);
 71→      }
 72→    }
 73→  }
 74→
 75→  return frag;
 76→}
 77→
 78→/**
 79→ * Parse inline markup (**bold** and `code`) and append nodes to parent.
 80→ */
 81→function _appendInlineMarkup(parent, text) {
 82→  // Tokenize on **bold** and `code` patterns
 83→  const tokens = text.split(/(\*\*[^*]+\*\*|`[^`]+`)/);
 84→
 85→  for (const token of tokens) {
 86→    if (token.startsWith("**") && token.endsWith("**")) {
 87→      // Bold
 88→      const strong = document.createElement("strong");
 89→      strong.className = "sd-text-bold";
 90→      strong.textContent = token.slice(2, -2);
 91→      parent.appendChild(strong);
 92→    } else if (token.startsWith("`") && token.endsWith("`")) {
 93→      // Inline code
 94→      const code = document.createElement("code");
 95→      code.className = "sd-code-inline";
 96→      code.textContent = token.slice(1, -1);
 97→      parent.appendChild(code);
 98→    } else if (token) {
 99→      _appendInlineText(parent, token);
100→    }
101→  }
102→}
103→
104→/**
105→ * Append plain text, converting single newlines to <br>.
106→ */
107→function _appendInlineText(parent, text) {
108→  const lines = text.split("\n");
109→  for (let i = 0; i < lines.length; i++) {
110→    if (i > 0) parent.appendChild(document.createElement("br"));
111→    if (lines[i]) parent.appendChild(document.createTextNode(lines[i]));
112→  }
113→}
114→
115→// ── Typing Indicator ───────────────────────────────────────────────
116→
117→export function createTypingIndicator() {
118→  const el = document.createElement("span");
119→  el.className = "sd-typing";
120→  for (let i = 0; i < 3; i++) {
121→    const dot = document.createElement("span");
122→    dot.className = "sd-typing__dot";
123→    el.appendChild(dot);
124→  }
125→  return el;
126→}
127→
128→// ── Panel Component Factories ──────────────────────────────────────
129→
130→/**
131→ * Create a colored slot tag chip.
132→ * @param {string} label - Node/concept name
133→ * @param {string} slotType - Slot type key (e.g., "model", "vae")
134→ */
135→export function createSlotTag(label, slotType) {
136→  const color = _slotColor(slotType);
137→  const tag = document.createElement("span");
138→  tag.className = "sd-slot-tag";
139→  tag.style.background = color + "1f"; // 12% opacity
140→  tag.style.border = `1px solid ${color}40`; // 25% opacity
141→  tag.style.color = color;
142→
143→  const dot = document.createElement("span");
144→  dot.className = "sd-slot-tag__dot";
145→  dot.style.background = color;
146→  dot.style.boxShadow = `0 0 4px ${color}8c`; // 55% glow
147→  tag.appendChild(dot);
148→
149→  const txt = document.createTextNode(label);
150→  tag.appendChild(txt);
151→
152→  return tag;
153→}
154→
155→/**
156→ * Create a collapsible section.
157→ * @param {string} title
158→ * @param {string} dotColor - CSS color string
159→ * @param {number|string} count - Badge count
160→ * @param {boolean} defaultOpen
161→ * @param {Function} buildBody - () => HTMLElement (lazy, called on first expand)
162→ */
163→export function createCollapsibleSection(title, dotColor, count, defaultOpen, buildBody) {
164→  const section = document.createElement("div");
165→  section.className = "sd-section" + (defaultOpen ? " sd-section--open" : "");
166→
167→  // Trigger button
168→  const trigger = document.createElement("button");
169→  trigger.className = "sd-section__trigger";
170→
171→  const dot = document.createElement("span");
172→  dot.className = "sd-section__dot";
173→  dot.style.background = dotColor;
174→  dot.style.boxShadow = `0 0 4px ${dotColor}8c`;
175→  trigger.appendChild(dot);
176→
177→  const titleEl = document.createElement("span");
178→  titleEl.className = "sd-section__title";
179→  titleEl.textContent = title;
180→  trigger.appendChild(titleEl);
181→
182→  if (count != null) {
183→    const countEl = document.createElement("span");
184→    countEl.className = "sd-section__count";
185→    countEl.textContent = String(count);
186→    trigger.appendChild(countEl);
187→  }
188→
189→  const chevron = document.createElement("span");
190→  chevron.className = "sd-section__chevron";
191→  chevron.textContent = "\u25b8"; // right-pointing triangle
192→  trigger.appendChild(chevron);
193→
194→  section.appendChild(trigger);
195→
196→  // Body (lazy)
197→  const body = document.createElement("div");
198→  body.className = "sd-section__body";
199→  let built = defaultOpen;
200→  if (defaultOpen && buildBody) {
201→    const content = buildBody();
202→    if (content) body.appendChild(content);
203→  }
204→  section.appendChild(body);
205→
206→  // Toggle
207→  trigger.addEventListener("click", () => {
208→    const isOpen = section.classList.toggle("sd-section--open");
209→    if (isOpen && !built && buildBody) {
210→      built = true;
211→      const content = buildBody();
212→      if (content) body.appendChild(content);
213→    }
214→  });
215→
216→  return section;
217→}
218→
219→/**
220→ * Create a flow chain showing signal path through nodes.
221→ * @param {Array<{label: string, slotType: string}>} nodes
222→ * @param {string} [pathLabel] - Optional path label prefix
223→ */
224→export function createFlowChain(nodes, pathLabel) {
225→  const chain = document.createElement("div");
226→  chain.className = "sd-flow-chain";
227→
228→  if (pathLabel) {
229→    const lbl = document.createElement("span");
230→    lbl.className = "sd-flow-chain__label";
231→    lbl.textContent = pathLabel;
232→    chain.appendChild(lbl);
233→  }
234→
235→  for (let i = 0; i < nodes.length; i++) {
236→    if (i > 0) {
237→      const arrow = document.createElement("span");
238→      arrow.className = "sd-flow-chain__arrow";
239→      arrow.textContent = "\u2192"; // →
240→      chain.appendChild(arrow);
241→    }
242→
243→    const node = document.createElement("span");
244→    node.className = "sd-flow-chain__node";
245→    const color = _slotColor(nodes[i].slotType);
246→    node.style.color = color;
247→    node.style.background = color + "1a"; // ~10% opacity
248→    node.textContent = nodes[i].label;
249→    chain.appendChild(node);
250→  }
251→
252→  return chain;
253→}
254→
255→/**
256→ * Create a key-value detail row with dotted leader.
257→ * @param {string} label
258→ * @param {string} value
259→ */
260→export function createDetailRow(label, value) {
261→  const row = document.createElement("div");
262→  row.className = "sd-detail-row";
263→
264→  const lbl = document.createElement("span");
265→  lbl.className = "sd-detail-row__label";
266→  lbl.textContent = label;
267→  row.appendChild(lbl);
268→
269→  const leader = document.createElement("span");
270→  leader.className = "sd-detail-row__leader";
271→  row.appendChild(leader);
272→
273→  const val = document.createElement("span");
274→  val.className = "sd-detail-row__value";
275→  val.textContent = value;
276→  row.appendChild(val);
277→
278→  return row;
279→}
280→
281→/**
282→ * Create a capability row.
283→ * @param {string} label
284→ * @param {string} desc
285→ * @param {string} [color] - Dot color, defaults to brand
286→ */
287→export function createCapabilityRow(label, desc, color) {
288→  const row = document.createElement("div");
289→  row.className = "sd-capability-row";
290→
291→  const dot = document.createElement("span");
292→  dot.className = "sd-capability-row__dot";
293→  dot.style.background = color || "var(--sd-brand)";
294→  row.appendChild(dot);
295→
296→  const lbl = document.createElement("span");
297→  lbl.className = "sd-capability-row__label";
298→  lbl.textContent = label;
299→  row.appendChild(lbl);
300→
301→  const sep = document.createElement("span");
302→  sep.className = "sd-capability-row__sep";
303→  row.appendChild(sep);
304→
305→  const d = document.createElement("span");
306→  d.className = "sd-capability-row__desc";
307→  d.textContent = desc;
308→  row.appendChild(d);
309→
310→  return row;
311→}
312→
313→/**
314→ * Create an action footer.
315→ * @param {string} status - Status text
316→ * @param {Array<{label: string, variant: string}>} actions - Buttons
317→ */
318→export function createActionFooter(status, actions) {
319→  const footer = document.createElement("div");
320→  footer.className = "sd-panel__footer";
321→
322→  const statusEl = document.createElement("span");
323→  statusEl.className = "sd-panel__footer-status";
324→  statusEl.textContent = status || "";
325→  footer.appendChild(statusEl);
326→
327→  if (actions && actions.length) {
328→    const actionsEl = document.createElement("div");
329→    actionsEl.className = "sd-panel__footer-actions";
330→    for (const action of actions) {
331→      const btn = document.createElement("button");
332→      btn.className = `sd-btn sd-btn--${action.variant || "secondary"}`;
333→      btn.textContent = action.label;
334→      actionsEl.appendChild(btn);
335→    }
336→    footer.appendChild(actionsEl);
337→  }
338→
339→  return footer;
340→}
341→
342→/**
343→ * Create a full panel from panelData.
344→ * @param {Object} panelData - Panel schema from backend
345→ * @returns {HTMLElement|null}
346→ *
347→ * panelData schema:
348→ * {
349→ *   type: "workflow_analysis"|"discovery"|"execution"|"error",
350→ *   header: { label, badge, title, summary, stats: [{value,label}] },
351→ *   sections: [{
352→ *     title, dotColor, count, defaultOpen,
353→ *     type: "flow_chain"|"slot_tags"|"capability_rows"|"detail_rows",
354→ *     data: { ... type-specific ... }
355→ *   }],
356→ *   footer: { status, actions: [{label,variant}] }
357→ * }
358→ */
359→export function createPanel(panelData) {
360→  if (!panelData) return null;
361→
362→  const panel = document.createElement("div");
363→  panel.className = "sd-panel";
364→
365→  // Header
366→  if (panelData.header) {
367→    const header = document.createElement("div");
368→    header.className = "sd-panel__header";
369→
370→    // Label row
371→    const labelRow = document.createElement("div");
372→    labelRow.className = "sd-panel__label-row";
373→
374→    const label = document.createElement("span");
375→    label.className = "sd-panel__label";
376→    label.textContent = panelData.header.label || "";
377→    labelRow.appendChild(label);
378→
379→    if (panelData.header.badge) {
380→      const badge = document.createElement("span");
381→      badge.className = "sd-panel__badge";
382→      badge.textContent = panelData.header.badge;
383→      labelRow.appendChild(badge);
384→    }
385→    header.appendChild(labelRow);
386→
387→    // Title
388→    if (panelData.header.title) {
389→      const title = document.createElement("div");
390→      title.className = "sd-panel__title";
391→      title.textContent = panelData.header.title;
392→      header.appendChild(title);
393→    }
394→
395→    // Summary
396→    if (panelData.header.summary) {
397→      const summary = document.createElement("div");
398→      summary.className = "sd-panel__summary";
399→      summary.textContent = panelData.header.summary;
400→      header.appendChild(summary);
401→    }
402→
403→    // Stats
404→    if (panelData.header.stats && panelData.header.stats.length) {
405→      const stats = document.createElement("div");
406→      stats.className = "sd-panel__stats";
407→      for (const s of panelData.header.stats) {
408→        const stat = document.createElement("div");
409→        stat.className = "sd-panel__stat";
410→
411→        const val = document.createElement("span");
412→        val.className = "sd-panel__stat-value";
413→        val.textContent = String(s.value);
414→        stat.appendChild(val);
415→
416→        const lbl = document.createElement("span");
417→        lbl.className = "sd-panel__stat-label";
418→        lbl.textContent = s.label;
419→        stat.appendChild(lbl);
420→
421→        stats.appendChild(stat);
422→      }
423→      header.appendChild(stats);
424→    }
425→
426→    panel.appendChild(header);
427→  }
428→
429→  // Sections
430→  if (panelData.sections) {
431→    for (const sec of panelData.sections) {
432→      const dotColor = sec.dotColor || "var(--sd-brand)";
433→      const section = createCollapsibleSection(
434→        sec.title,
435→        dotColor,
436→        sec.count,
437→        sec.defaultOpen || false,
438→        () => _buildSectionBody(sec)
439→      );
440→      panel.appendChild(section);
441→    }
442→  }
443→
444→  // Footer
445→  if (panelData.footer) {
446→    const footer = createActionFooter(
447→      panelData.footer.status,
448→      panelData.footer.actions
449→    );
450→    panel.appendChild(footer);
451→  }
452→
453→  return panel;
454→}
455→
456→/**
457→ * Build the body content for a section based on its type.
458→ */
459→function _buildSectionBody(sec) {
