 61→  --sd-space-lg: 12px;
 62→  --sd-space-xl: 16px;
 63→  --sd-space-2xl: 24px;
 64→  --sd-space-3xl: 32px;
 65→  --sd-msg-gap: 20px;
 66→  --sd-para-gap: 12px;
 67→
 68→  --sd-transition: 150ms ease;
 69→}
 70→
 71→/* ── Layout Shell ───────────────────────────────────────────────── */
 72→
 73→.sd-header {
 74→  display: flex;
 75→  align-items: center;
 76→  justify-content: space-between;
 77→  padding: var(--sd-space-lg) var(--sd-space-xl);
 78→  font-family: var(--sd-font-sans);
 79→  font-size: 13px;
 80→  font-weight: 500;
