        output_mapping = [{"old_idx": 0, "new_idx": 0}]
        patches = _build_migration_patches(
            "1", node_data, "NewNode", [], output_mapping, workflow
        )
        conn_patches = [p for p in patches if "/2/" in p["path"]]
        assert len(conn_patches) == 0
