    if name == "_OPTIMIZATIONS":
        return _OPTIMIZATIONS
    if name == "_GPU_HEAVY_NODES":
        return _GPU_HEAVY_NODES
    if name == "_TRT_PACKS":
        return _TRT_PACKS
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

